// One source-time clock drives the audio, score and lyrics.
const T=ChordTimeline;
let playing=false,position=0,anchor=0,frame=0,lastBar=-1,lastLyric=-1,lyricRows=[],editorRows=[];
const audio=$('audio');
const builtinLyrics={
 arirang:[[0,'아리랑 아리랑 아라리요'],[4,'아리랑 고개로 넘어간다'],[8,'나를 버리고 가시는 님은'],[12,'십 리도 못 가서 발병 난다']],
 twinkle:[[0,'Twinkle, twinkle, little star,'],[2,'How I wonder what you are!'],[4,'Up above the world so high,'],[6,'Like a diamond in the sky.'],[8,'Twinkle, twinkle, little star,'],[12,'How I wonder what you are!'],[16,'Twinkle, twinkle, little star,'],[20,'How I wonder what you are!']]
};
function hasAudio(){return !!audio.getAttribute('src')}
function baseTimeline(){return T.timing(current)}
function duration(){return hasAudio()&&Number.isFinite(audio.duration)?audio.duration:baseTimeline().duration}
function rate(){return Number($('speed').value)*(hasAudio()?1:Number($('bpm').value)/(current.bpm||80))}
function time(){return hasAudio()?audio.currentTime:Math.min(duration(),position+(playing?(performance.now()-anchor)/1000*rate():0))}
function setPlaying(value){playing=value;$('scorePlay').textContent=value?'Ⅱ 일시정지':'▶ 악보 재생';$('scorePlay').setAttribute('aria-pressed',String(value));cancelAnimationFrame(frame);if(value)frame=requestAnimationFrame(loop)}
function pauseScore(){position=time();audio.pause();setPlaying(false);paint()}
function seekScore(t){const next=Math.max(0,Math.min(duration(),t));position=next;anchor=performance.now();if(hasAudio())audio.currentTime=next;paint()}
async function playScore(){if(time()>=duration()-.03)seekScore(0);if(hasAudio()){audio.playbackRate=rate();try{await audio.play()}catch{ $('syncStatus').textContent='음원을 재생하지 못했습니다. 파일을 다시 연결해주세요.';return}}else{anchor=performance.now();setPlaying(true)}paint()}
function loop(){paint();if(time()>=duration()&&!hasAudio()){position=duration();setPlaying(false);paint();return}if(playing)frame=requestAnimationFrame(loop)}
function paint(){if(!current)return;const now=time();$('seekScore').max=duration();$('seekScore').value=now;$('scoreTime').textContent=format(now)+' / '+format(duration());const i=T.indexAt(baseTimeline().starts,now);if(i!==lastBar){document.querySelectorAll('.bar').forEach((el,k)=>{el.classList.toggle('active',k===i);el.setAttribute('aria-current',k===i?'true':'false')});lastBar=i}const adjusted=now-Number($('lyricOffset').value||0);const l=T.indexAt(lyricRows.map(r=>r.time),adjusted);if(l!==lastLyric){const rows=document.querySelectorAll('.lyric-line');rows.forEach((el,k)=>{el.classList.toggle('active',k===l);el.setAttribute('aria-current',k===l?'true':'false')});if(l>=0&&rows[l]&&$('followLyrics').checked)rows[l].scrollIntoView({behavior:'smooth',block:'nearest'});lastLyric=l}if(i>=0){const chord= current.sections.flatMap(s=>s[1])[i];$('nowChord').textContent=chord.split(' ').map(c=>T.chord(c,transpose-Number($('capo').value))).join(' · ')}else $('nowChord').textContent='—'}
function renderLyrics(){lyricRows=(current.lyrics||[]).slice().sort((a,b)=>a.time-b.time);$('lyrics').replaceChildren();if(!lyricRows.length){$('lyrics').innerHTML='<p class="lyrics-empty">가사를 추가하면 재생 위치에 맞춰 코드와 함께 진행됩니다.<br>가사 입력 또는 시간 정보가 있는 LRC 파일을 사용하세요.</p>'}lyricRows.forEach((r,k)=>{const b=document.createElement('button');b.className='lyric-line';b.innerHTML='<small>'+format(r.time)+'</small><span>'+esc(r.text||'♪ 간주')+'</span>';b.onclick=()=>seekScore(r.time+Number($('lyricOffset').value||0));$('lyrics').append(b)});lastLyric=-2;paint()}
const originalOpen=openSheet;
openSheet=function(song){if(current)pauseScore();position=0;lastBar=-2;lastLyric=-2;if(!song.audio)audio.removeAttribute('src');originalOpen(song);$('speed').value='1';$('bpm').disabled=hasAudio();$('lyricOffset').value=current.lyricOffset||0;if(!current.lyrics&&builtinLyrics[current.id])current.lyrics=builtinLyrics[current.id].map(([bar,text])=>({time:baseTimeline().starts[bar],text}));$('audioWrap').hidden=!hasAudio();$('syncStatus').textContent=hasAudio()?'음원 재생 위치에 가사와 코드를 맞춥니다.':'BPM 기준 악보 진행입니다. 원곡 음성은 포함되지 않습니다.';bindBars();renderLyrics();paint()};
const originalRender=renderSheet;
renderSheet=function(){originalRender();if(!current)return;$('capoSummary').textContent='실제 조성 '+T.chord(current.key,transpose)+' · 잡는 코드 조성 '+T.chord(current.key,transpose-Number($('capo').value))+' · 카포 '+$('capo').value+'프렛';lastBar=-2;bindBars();paint()};
function bindBars(){if(!current)return;document.querySelectorAll('.bar').forEach((b,i)=>{b.tabIndex=0;b.setAttribute('role','button');b.setAttribute('aria-label', (i+1)+'번째 코드로 이동');b.onclick=()=>seekScore(baseTimeline().starts[i]);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}}})}
$('capo').onchange=()=>renderSheet();
$('scorePlay').onclick=()=>playing?pauseScore():playScore();$('scoreStop').onclick=()=>{pauseScore();seekScore(0)};$('seekScore').oninput=()=>seekScore(Number($('seekScore').value));
// Capture the old rate's position before the controls change it.
let oldBpm=80,oldSpeed=1;
function preserveClock(){if(!current)return;if(!hasAudio()&&playing){position=Math.min(duration(),position+(performance.now()-anchor)/1000*oldSpeed*oldBpm/(current.bpm||80));anchor=performance.now()}oldBpm=Number($('bpm').value);oldSpeed=Number($('speed').value);if(hasAudio())audio.playbackRate=rate();paint()}
$('speed').onchange=preserveClock;$('bpm').onchange=()=>{const value=Number($('bpm').value);if(!Number.isFinite(value)||value<30||value>240)$('bpm').value=current?.bpm||80;stopMetro();preserveClock()};
const openWithRate=openSheet;openSheet=function(song){openWithRate(song);oldBpm=Number($('bpm').value);oldSpeed=1};
audio.ontimeupdate=paint;audio.addEventListener('play',()=>setPlaying(true));audio.addEventListener('pause',()=>{position=audio.currentTime;setPlaying(false);paint()});audio.addEventListener('ended',()=>{setPlaying(false);paint()});audio.addEventListener('seeked',paint);audio.addEventListener('loadedmetadata',()=>{if(current){$('bpm').disabled=hasAudio();paint()}});audio.addEventListener('ratechange',()=>{const v=String(audio.playbackRate);if([...$('speed').options].some(o=>o.value===v))$('speed').value=v;oldSpeed=audio.playbackRate});
audio.addEventListener('loadedmetadata',()=>{$('audioWrap').querySelector('p').textContent=current?.audio?'코드 분석 결과는 추정값입니다. 가사와 코드를 누르면 해당 위치로 이동합니다.':'연결한 음원의 재생 위치를 따라갑니다. 가사와 코드를 누르면 해당 위치로 이동합니다.'});
$('lyricOffset').oninput=()=>{if(!current)return;current.lyricOffset=Number($('lyricOffset').value)||0;const i=saved.findIndex(s=>s.id===current.id);if(i>=0){saved[i]=JSON.parse(JSON.stringify(current));persist()}lastLyric=-2;paint()};
const closeOriginal=$('closeSheet').onclick;$('closeSheet').onclick=()=>{pauseScore();closeOriginal()};
function saveEdits(){const i=saved.findIndex(s=>s.id===current.id);if(i>=0){saved[i]=JSON.parse(JSON.stringify(current));persist()}$('syncStatus').textContent='가사·싱크를 적용했습니다. ♡ 저장으로 이 기기에 보관할 수 있습니다.'}
function renderEditor(){ $('editorLines').replaceChildren();editorRows.forEach((r,i)=>{const row=document.createElement('div');row.className='editor-line';row.innerHTML='<input type="number" min="0" step="0.1" aria-label="'+(i+1)+'번째 가사 시작 초" value="'+r.time.toFixed(2)+'"><span>'+esc(r.text||'♪ 간주')+'</span><button type="button">현재 위치</button>';row.querySelector('input').onchange=e=>r.time=Math.max(0,Number(e.target.value)||0);row.querySelector('button').onclick=()=>{r.time=time();row.querySelector('input').value=r.time.toFixed(2)};$('editorLines').append(row)})}
$('editLyrics').onclick=()=>{if(!current)return;editorRows=(current.lyrics||[]).map(r=>({...r}));$('lyricInput').value=T.toLRC(editorRows);renderEditor();$('lyricsDialog').showModal()};$('lyricsDialogClose').onclick=()=>$('lyricsDialog').close();
$('prepareLyrics').onclick=()=>{const text=$('lyricInput').value.trim();const parsed=T.parseLRC(text);if(parsed.length)editorRows=parsed;else{const lines=text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);editorRows=lines.map((text,i)=>({time:duration()*i/lines.length,text}))}$('editorHint').textContent=parsed.length?'LRC 시간을 가져왔습니다. 필요하면 시작 초를 조절하세요.':'줄 간격을 균등하게 임시 배치했습니다. 음원을 들으며 현재 위치 버튼으로 정확한 타이밍을 지정하세요.';renderEditor()};
$('applyLyrics').onclick=()=>{current.lyrics=editorRows.map(r=>({time:Math.max(0,Number(r.time)||0),text:r.text})).sort((a,b)=>a.time-b.time);renderLyrics();saveEdits();$('lyricsDialog').close()};
$('lrcFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>1024*1024){$('editorHint').textContent='1MB 이하 LRC 파일을 선택해주세요.';return}$('lyricInput').value=await f.text();$('prepareLyrics').click()};
$('exportLrc').onclick=()=>{if(!current)return;const text=T.toLRC((current.lyrics||[]).map(r=>({...r,time:Math.max(0,r.time+Number($('lyricOffset').value||0))})));const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=current.title+'.lrc';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('attachAudioBtn').onclick=()=>$('attachAudio').click();$('attachAudio').onchange=e=>{const f=e.target.files[0];e.target.value='';if(!f||!current)return;if(f.size>100*1024*1024){$('syncStatus').textContent='100MB 이하 음원을 선택해주세요.';return}pauseScore();if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(f);window.activeAudioId=current.id;audio.src=objectUrl;audio.playbackRate=Number($('speed').value);position=0;$('audioWrap').hidden=false;$('syncStatus').textContent='음원을 연결했습니다. 가사 편집에서 줄별 시작 시간을 맞춰주세요. 파일은 서버로 전송하지 않습니다.'};audio.addEventListener('error',()=>{$('syncStatus').textContent='음원을 열 수 없습니다. MP3·WAV 파일을 다시 연결해주세요.'});
// Timing capture and playback controls are available inside the editor.
$('editorPlay').onclick=()=>playing?pauseScore():playScore();
